  &reftitle.examples;

   Printing a binary string as text


<?php

echo snmp2_get('localhost', 'public', 'SNMP-FRAMEWORK-MIB::snmpEngineID.0'), PHP_EOL;

snmp_set_string_output_format(Snmp\StringOutput::Ascii);
echo snmp2_get('localhost', 'public', 'SNMP-FRAMEWORK-MIB::snmpEngineID.0'), PHP_EOL;

?>


